# figure_house_theme.R — the ONE ggplot theme for every Chapter 2 figure.
#
# PJ, 17 Aug 2026: "need to standardise fonts and presentation of panels across all figures."
#
# ⛔ THIS IS NOT A NEW STANDARD. It is FIGURE_STYLE_GUIDE.md (25 Jul 2026) turned into code so it
# cannot drift again. Where the guide and a figure disagreed, the GUIDE WINS. Do not change the
# values here to match a figure; change the figure.
#
# The guide, verbatim on the points this file implements:
#   - theme_minimal(base_size ~ 10); no minor gridlines; no vertical (x) major gridlines;
#     legend.position = "none"
#   - Panel tags A/B/C BOLD; subtitles ITALIC grey30, factual; axis titles grey20
#   - Title = bold, prefixed "Figure 2.X"
#   - Sources OFF the figure (footnote only)
#   - Draft output PNG, dpi ~ 200
#
# ⚠ PANEL LETTERS USE labs(tag = "A"), NOT an "A. " prefix on the subtitle. On 17 Aug several
# figures were briefly normalised the other way before this guide was consulted; that was wrong and
# has been reverted. One mechanism only, and it is the tag.
#
# Usage:
#   source("<workspace>/figure_house_theme.R")
#   ... + labs(tag = "A", subtitle = "What this panel shows") + house()
#   ggsave(out, fig, width = ..., height = ..., dpi = HOUSE_DPI, bg = "white")

house <- function(base_size = 10) {
  ggplot2::theme_minimal(base_size = base_size) +
    ggplot2::theme(
      legend.position    = "none",
      panel.grid.minor   = ggplot2::element_blank(),
      panel.grid.major.x = ggplot2::element_blank(),
      panel.grid.major.y = ggplot2::element_line(colour = "grey90", linewidth = 0.3),
      plot.title         = ggplot2::element_text(face = "bold", size = 11),
      plot.subtitle      = ggplot2::element_text(face = "italic", colour = "grey30", size = 9),
      plot.tag           = ggplot2::element_text(face = "bold", size = 11),
      plot.caption       = ggplot2::element_text(size = 7, colour = "grey40", hjust = 0),
      axis.title         = ggplot2::element_text(size = 9, colour = "grey20"),
      axis.text          = ggplot2::element_text(size = 8, colour = "grey20")
    )
}

# The figure-level title block (used in patchwork's plot_annotation).
house_title <- function(size = 11.5) {
  ggplot2::theme(plot.title = ggplot2::element_text(face = "bold", size = size,
                                                    margin = ggplot2::margin(b = 10)))
}

# ============================================================================
# OUTPUT MODE — one switch, so production is a one-line change and not 11 edits
# ============================================================================
# PJ, 17 Aug: "do what we can" — the book has three stages: (a) finished,
# (b) out to review, (c) revised before submission. ⭐ (c) is the key stage, and that is when
# BUP's production spec has to be met. Until then DRAFT is correct and sufficient.
#
# ⛔ DO NOT rebuild every figure to print spec now. Flip HOUSE_MODE at stage (c) instead.

HOUSE_MODE <- "draft"        # "draft" (a/b) or "production" (c)

# BUP spec, Editorial-and-Production-Guidelines.pdf, Artwork p.11 + Appendix D p.27:
#   - figures 120 mm wide to fill the page width (exact size depends on format)
#   - minimum 300 dpi AT PRINT SIZE, i.e. >= 1440 px wide
#   - black and white as standard across ALL formats, print AND digital
#   - separate files, never embedded in Word; EPS named as the format for line drawings
HOUSE_WIDTH_MM <- if (HOUSE_MODE == "production") 120 else 165
HOUSE_DPI      <- if (HOUSE_MODE == "production") 300 else 200

house_width_in <- function() HOUSE_WIDTH_MM / 25.4

# ============================================================================
# ⭐ PRINT-RELATIVE TYPE — added 17 Aug 2026
# ============================================================================
# PJ, 17 Aug: "the subheading in 2.6 are really small - is that what we want?"
#
# ⛔ THE DIAGNOSIS: every figure sets subtitle size 9, so the SCRIPTS look consistent. They are
# not consistent ON THE PAGE. Canvases run 6.5-9 in; at BUP's 120 mm column the same "size 9"
# prints at 6.5 pt on a 6.5 in figure and 4.7 pt on a 9 in one. Fixing the raw number produced
# inconsistent printed type, which is the opposite of the intention.
#
# ⭐ THE RULE: specify type at its PRINTED size and let the canvas width do the arithmetic.
#   raw_pt = printed_pt * canvas_width_in / 4.724
# Raw sizes therefore look far too large in the PNG. That is correct and expected — the PNG is
# an intermediate, the page is the product.

PRINT_WIDTH_IN <- 120 / 25.4                     # 4.724 in — BUP's full-page figure width

pt_for <- function(printed_pt, canvas_width_in) printed_pt * canvas_width_in / PRINT_WIDTH_IN
# geom_text()/annotate() take size in MILLIMETRES, not points.
mm_for <- function(printed_pt, canvas_width_in) pt_for(printed_pt, canvas_width_in) / 2.845

# Target PRINTED sizes. BUP's practical floor is about 7 pt; 8 pt is comfortable.
PRINTED <- list(title = 10, subtitle = 8, tag = 9, axis_title = 8, axis_text = 7,
                caption = 6.5, in_panel = 7)

# House theme sized for a given canvas width.
house_print <- function(canvas_width_in) {
  P <- function(k) pt_for(PRINTED[[k]], canvas_width_in)
  ggplot2::theme_minimal(base_size = P("axis_text")) +
    ggplot2::theme(
      legend.position    = "none",
      panel.grid.minor   = ggplot2::element_blank(),
      panel.grid.major.x = ggplot2::element_blank(),
      panel.grid.major.y = ggplot2::element_line(colour = "grey90", linewidth = 0.3),
      plot.title         = ggplot2::element_text(face = "bold", size = P("title")),
      plot.subtitle      = ggplot2::element_text(face = "italic", colour = "grey30", size = P("subtitle")),
      plot.tag           = ggplot2::element_text(face = "bold", size = P("tag")),
      plot.caption       = ggplot2::element_text(size = P("caption"), colour = "grey40", hjust = 0),
      axis.title         = ggplot2::element_text(size = P("axis_title"), colour = "grey20"),
      axis.text          = ggplot2::element_text(size = P("axis_text"), colour = "grey20")
    )
}

# ⚠ SCALING TYPE UP DOES NOT CREATE SPACE. A 9 in layout reduced to 120 mm has the same number
# of labels in a third of the area; enlarging the type can make them collide instead of merely
# being small. If a figure breaks under house_print(), the canvas is carrying more than a 120 mm
# column can hold and the fix is to simplify or split it, not to shrink the type again.
# ⛔ TEST ONE FIGURE AND LOOK AT IT BEFORE APPLYING THIS ACROSS THE CHAPTER.

# ⛔ THE REAL CONSTRAINT IS TYPE SIZE AFTER REDUCTION, NOT RESOLUTION.
# A 9-inch-wide figure printed at 120 mm is reduced to 53%: base_size 10 lands at about 5 pt on the
# page, which is unreadable. At 6.5 in the reduction is to 73% and type lands near 7 pt. Raising dpi
# does nothing for this. ⚠ Worst affected are the multi-panel figures (2.9 and 2.10 are built 9 in
# wide, 2.11 is 8.5 in). At stage (c), either build at 120 mm with type set for it, or raise
# base_size so type survives the reduction, or split the tall figures. Test ONE before doing all.
